use strict;
use warnings;
use MT;
use MT::Builder;
use MT::Template::Context;
MT->new(Config => 'mt-config.cgi') or die MT->errstr;
my $ctx = MT::Template::Context->new;
my $builder = MT::Builder->new;
open my $fh, '<', 'hello.mtml' or die $!;
local $/; my $text = <$fh>;
my $tokens = $builder->compile($ctx, $text) or die($builder->errstr);
my $result = $builder->build($ctx, $tokens);
die($builder->errstr) unless defined $result;
print $result;
